(function(){
  const style=document.createElement('style');style.textContent='.change-password-button{border:1px solid var(--line);background:var(--white);color:var(--ink);border-radius:9px;padding:8px 11px;font-size:13px;font-weight:750}.change-password-button:hover{border-color:var(--blue)}.change-password-modal{max-width:430px}.change-password-modal .primary{margin-top:14px}';document.head.appendChild(style);
  const resident=document.querySelector('.resident');if(!resident)return;
  const button=document.createElement('button');button.className='change-password-button';button.id='changePasswordButton';button.type='button';button.textContent='Alterar senha';resident.insertBefore(button,resident.firstChild);
  const modal=document.createElement('div');modal.className='modal-back hidden';modal.id='changePasswordModal';modal.innerHTML='<div class="modal change-password-modal"><h3>Alterar senha</h3><p>Crie uma nova senha para acessar o portal.</p><label for="changePasswordValue">Nova senha</label><input id="changePasswordValue" type="password" minlength="8" autocomplete="new-password" placeholder="Mínimo de 8 caracteres"><label for="changePasswordConfirm">Confirmar nova senha</label><input id="changePasswordConfirm" type="password" minlength="8" autocomplete="new-password" placeholder="Repita a senha"><button class="primary" id="changePasswordSave" type="button">Salvar nova senha</button><div class="error" id="changePasswordError"></div></div>';document.body.appendChild(modal);
  const close=()=>{modal.classList.add('hidden');document.getElementById('changePasswordValue').value='';document.getElementById('changePasswordConfirm').value='';document.getElementById('changePasswordError').textContent=''};
  button.onclick=()=>modal.classList.remove('hidden');
  document.getElementById('changePasswordSave').onclick=async()=>{const value=document.getElementById('changePasswordValue').value,confirm=document.getElementById('changePasswordConfirm').value,error=document.getElementById('changePasswordError');if(value.length<8||value!==confirm){error.textContent='Use pelo menos 8 caracteres e confirme a mesma senha.';return}try{await window.ltApi('/api/password',{method:'PATCH',body:JSON.stringify({password:value})});close();show('Senha alterada com sucesso.')}catch(err){error.textContent=err.message}};
  const oldOpenApp=openApp;openApp=user=>{oldOpenApp(user);button.classList.remove('hidden')};
})();
